#include <stdint.h>

#define TRAFFIC_GENERATOR_CONTROL_REG_OFFSET              0x00u
#define TRAFFIC_GENERATOR_CONFIG_REG_OFFSET               0x04u
#define TRAFFIC_GENERATOR_STATUS_REG_OFFSET               0x08u
