#define TRAFFIC_GENERATOR_ADDRESS_MASK_REG_OFFSET         0x10u
#define TRAFFIC_GENERATOR_STRIDE_REG_OFFSET               0x14u
#define TRAFFIC_GENERATOR_SEED_REG_OFFSET                 0x18u
#define TRAFFIC_GENERATOR_WRITE_DATA_REG_OFFSET           0x1cu
#define TRAFFIC_GENERATOR_BYTE_ENABLE_REG_OFFSET          0x20u
#define TRAFFIC_GENERATOR_INJECTION_RATE_REG_OFFSET       0x24u
#define TRAFFIC_GENERATOR_PERIOD_REG_OFFSET               0x28u
#define TRAFFIC_GENERATOR_BURST_LENGTH_REG_OFFSET         0x2cu
#define TRAFFIC_GENERATOR_IDLE_LENGTH_REG_OFFSET          0x30u
#define TRAFFIC_GENERATOR_DURATION_LIMIT_REG_OFFSET       0x34u
#define TRAFFIC_GENERATOR_IRQ_ENABLE_REG_OFFSET           0x38u
#define TRAFFIC_GENERATOR_IRQ_STATUS_REG_OFFSET           0x3cu
#define TRAFFIC_GENERATOR_ELAPSED_CYCLES_REG_OFFSET       0x40u
#define TRAFFIC_GENERATOR_REQUESTS_REG_OFFSET             0x44u
#define TRAFFIC_GENERATOR_GRANTS_REG_OFFSET               0x48u
#define TRAFFIC_GENERATOR_COMPLETED_REG_OFFSET            0x4cu
#define TRAFFIC_GENERATOR_READS_REG_OFFSET                0x50u
#define TRAFFIC_GENERATOR_WRITES_REG_OFFSET               0x54u
#define TRAFFIC_GENERATOR_WAIT_GRANT_CYCLES_REG_OFFSET    0x58u
#define TRAFFIC_GENERATOR_WAIT_RESPONSE_CYCLES_REG_OFFSET 0x5cu
#define TRAFFIC_GENERATOR_LATENCY_SUM_REG_OFFSET          0x60u
#define TRAFFIC_GENERATOR_LATENCY_MAX_REG_OFFSET          0x64u
#define TRAFFIC_GENERATOR_MISSED_OPPORTUNITIES_REG_OFFSET 0x68u
#define TRAFFIC_GENERATOR_LAST_ADDRESS_REG_OFFSET         0x6cu
#define TRAFFIC_GENERATOR_PRNG_STATE_REG_OFFSET           0x70u
#define TRAFFIC_GENERATOR_ERROR_STATUS_REG_OFFSET         0x74u
#define TRAFFIC_GENERATOR_VERSION_REG_OFFSET              0x78u
#define TRAFFIC_GENERATOR_LAST_READ_DATA_REG_OFFSET       0x7cu
#define TRAFFIC_GENERATOR_TEMPORAL_PRNG_STATE_REG_OFFSET  0x80u

#define TRAFFIC_GENERATOR_CONTROL_START_MASK       (1u << 0)
#define TRAFFIC_GENERATOR_CONTROL_STOP_MASK        (1u << 1)
#define TRAFFIC_GENERATOR_CONTROL_SOFT_RESET_MASK  (1u << 2)
#define TRAFFIC_GENERATOR_CONTROL_CLEAR_DONE_MASK  (1u << 3)
#define TRAFFIC_GENERATOR_CONTROL_CLEAR_ERROR_MASK (1u << 4)

#define TRAFFIC_GENERATOR_CONFIG_ADDRESS_MODE_OFFSET     0u
#define TRAFFIC_GENERATOR_CONFIG_ADDRESS_MODE_MASK       (0x7u << 0)
#define TRAFFIC_GENERATOR_CONFIG_TEMPORAL_MODE_OFFSET    4u
#define TRAFFIC_GENERATOR_CONFIG_TEMPORAL_MODE_MASK      (0x7u << 4)
#define TRAFFIC_GENERATOR_CONFIG_DURATION_MODE_OFFSET    8u
#define TRAFFIC_GENERATOR_CONFIG_DURATION_MODE_MASK      (0x3u << 8)
#define TRAFFIC_GENERATOR_CONFIG_RW_MODE_OFFSET          12u
#define TRAFFIC_GENERATOR_CONFIG_RW_MODE_MASK            (0x3u << 12)
#define TRAFFIC_GENERATOR_CONFIG_WRITE_DATA_MODE_OFFSET  16u
#define TRAFFIC_GENERATOR_CONFIG_WRITE_DATA_MODE_MASK    (0x3u << 16)

#define TRAFFIC_GENERATOR_STATUS_IDLE_MASK                (1u << 0)
#define TRAFFIC_GENERATOR_STATUS_RUNNING_MASK             (1u << 1)
#define TRAFFIC_GENERATOR_STATUS_DRAINING_MASK            (1u << 2)
#define TRAFFIC_GENERATOR_STATUS_DONE_MASK                (1u << 3)
#define TRAFFIC_GENERATOR_STATUS_ERROR_MASK               (1u << 4)
#define TRAFFIC_GENERATOR_STATUS_REQUEST_PENDING_MASK     (1u << 5)
#define TRAFFIC_GENERATOR_STATUS_RESPONSE_PENDING_MASK    (1u << 6)
#define TRAFFIC_GENERATOR_STATUS_STATE_OFFSET             24u
#define TRAFFIC_GENERATOR_STATUS_STATE_MASK               0x3u

#define TRAFFIC_GENERATOR_STATE_IDLE     0u
#define TRAFFIC_GENERATOR_STATE_RUNNING  1u
#define TRAFFIC_GENERATOR_STATE_DRAINING 2u
#define TRAFFIC_GENERATOR_STATE_DONE     3u

#define TRAFFIC_GENERATOR_IRQ_DONE_MASK  (1u << 0)
#define TRAFFIC_GENERATOR_IRQ_ERROR_MASK (1u << 1)
#define TRAFFIC_GENERATOR_IRQ_ALL_MASK   0x3u

#define TRAFFIC_GENERATOR_ERROR_START_WHILE_BUSY_MASK  (1u << 0)
#define TRAFFIC_GENERATOR_ERROR_CONFIG_WHILE_BUSY_MASK (1u << 1)
#define TRAFFIC_GENERATOR_ERROR_INVALID_CONFIG_MASK    (1u << 2)
#define TRAFFIC_GENERATOR_ERROR_UNEXPECTED_RESPONSE_MASK (1u << 3)
#define TRAFFIC_GENERATOR_ERROR_RESET_WHILE_BUSY_MASK  (1u << 4)
#define TRAFFIC_GENERATOR_ERROR_ALL_MASK               0x1fu

#define TRAFFIC_GENERATOR_EXPECTED_VERSION 0x00010000u

#endif /* TRAFFIC_GENERATOR_REGS_H_ */
